// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title AgentReputation
 * @notice 信誉分双轨计算：硬准确率 70% + 软共识率 30%
 * @dev 基于 v0.4 文档 §4.5 信誉分双轨
 */
library AgentReputation {
    using Math for uint256;

    struct Reputation {
        uint256 hardAccuracy;      // 硬准确率：链上事实一致性（0-10000，basis points）
        uint256 softConsensus;     // 软共识率：市场/Agent共识一致性（0-10000）
        uint256 observationEnd;      // 观察期结束时间戳
        uint256 consecutiveCorrect;// 连续独行正确次数
        uint256 totalCases;        // 参与总案例数
        uint256 correctCases;      // 正确案例数
    }

    uint256 constant OBSERVATION_PERIOD = 30 days;
    uint256 constant HARD_WEIGHT = 7000;  // 70%
    uint256 constant SOFT_WEIGHT = 3000;  // 30%
    uint256 constant HIGH_INDEPENDENCE_THRESHOLD = 3; // 连续3次独行正确→高独立判断力

    /**
     * @notice 计算综合信誉分
     * @param rep Reputation 结构体
     * @return score 综合信誉分（0-10000）
     */
    function calculateScore(Reputation storage rep) internal view returns (uint256 score) {
        require(block.timestamp >= rep.observationEnd, "AR: observation period not ended");

        if (rep.totalCases == 0) return 0;

        // 硬准确率 = correctCases / totalCases
        uint256 hard = (rep.correctCases * 10000) / rep.totalCases;

        // 综合分 = 硬准确率 * 70% + 软共识率 * 30%
        score = (hard * HARD_WEIGHT + rep.softConsensus * SOFT_WEIGHT) / 10000;

        // 高独立判断力权重动态提升：连续3次独行正确额外+10%
        if (rep.consecutiveCorrect >= HIGH_INDEPENDENCE_THRESHOLD) {
            score = Math.min(score + 1000, 10000); // +10%，上限100%
        }

        return score;
    }

    /**
     * @notice 记录案例结果
     * @param rep Reputation 结构体
     * @param isCorrect 是否正确
     * @param isSoloCorrect 是否独行正确（其他Agent都错，只有你对）
     */
    function recordCase(Reputation storage rep, bool isCorrect, bool isSoloCorrect) internal {
        if (block.timestamp < rep.observationEnd) {
            // 观察期内只统计，不计入最终分
            return;
        }

        rep.totalCases++;
        if (isCorrect) {
            rep.correctCases++;
            if (isSoloCorrect) {
                rep.consecutiveCorrect++;
            } else {
                rep.consecutiveCorrect = 0;
            }
        } else {
            rep.consecutiveCorrect = 0;
        }
    }

    /**
     * @notice 初始化观察期
     */
    function startObservation(Reputation storage rep) internal {
        rep.observationEnd = block.timestamp + OBSERVATION_PERIOD;
    }
}

contracts/CreatorConfig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title CreatorConfig
 * @notice 创作者配置：版本 DAG + TOPUP 定价锚定 + 链下存储
 * @dev 基于 v0.4 文档 §1.x
 */
contract CreatorConfig {

    // ============ 枚举 ============

    enum MigrationMode {
        None,       // 无迁移
        Sunset,     // 日落
        TOPUP,      // 补差价
        Fork        // 分叉
    }

    enum PriceDirection {
        Increase,   // 涨价
        Decrease,   // 降价
        Same        // 不变
    }

    // ============ 数据结构 ============

    struct Version {
        uint256 id;
        uint256 parentId;         // 父版本 ID（0 = 创世）
        bytes32 configHash;       // 配置哈希
        bytes32 contractHash;     // 合约字节码哈希
        uint256 publishTime;
        uint256 childCount;
        MigrationMode migrationMode;
        bool exists;
    }

    struct TOPUPricing {
        uint256 oldPrice;
        uint256 newPrice;
        uint256 announceTime;     // 公示开始时间
        uint256 twapPrice;        // 时间加权平均价格
        uint256 challengeDeadline;  // 社区质疑截止
        bool challenged;            // 是否被质疑
        PriceDirection direction;   // 价格方向
    }

    struct ChainStorage {
        string ipfsHash;          // IPFS 内容哈希
        bytes32 merkleRoot;       // Merkle root
        uint256 pinCount;         // Pinning 节点数
        uint256 lastVerified;     // 上次验证时间
    }

    // ============ 常量 ============

    uint256 public constant ANNOUNCE_PERIOD = 3 days;       // TOPUP 公示期
    uint256 public constant TWAP_WINDOW = 7 days;         // TWAP 窗口
    uint256 public constant CHALLENGE_WINDOW = 2 days;      // 社区质疑窗口
    uint256 public constant MAX_CONFIG_SIZE = 10240;        // 10KB 配置上限

    // ============ 状态变量 ============

    mapping(uint256 => Version) public versions;
    mapping(uint256 => TOPUPricing) public topuPricings;
    mapping(uint256 => ChainStorage) public chainStorages;
    mapping(bytes32 => uint256) public configKeys;        // key => value

    uint256 public nextVersionId;
    address public owner;
    address public licenseContract;

    // ============ 事件 ============

    event VersionPublished(
        uint256 indexed id,
        uint256 indexed parentId,
        bytes32 configHash,
        MigrationMode mode
    );
    event TOPUAnnounced(
        uint256 indexed versionId,
        uint256 oldPrice,
        uint256 newPrice,
        uint256 twap
    );
    event TOPUChallenged(uint256 indexed versionId, address challenger);
    event ChainStorageUpdated(uint256 indexed versionId, string ipfsHash, bytes32 merkleRoot);
    event ConfigSet(bytes32 indexed key, uint256 value);

    // ============ 修饰器 ============

    modifier onlyOwner() {
        require(msg.sender == owner, "CC: not owner");
        _;
    }

    // ============ 构造函数 ============

    constructor() {
        owner = msg.sender;
        nextVersionId = 1;  // 版本 ID 从 1 开始
    }

    function setLicenseContract(address _license) external onlyOwner {
        licenseContract = _license;
    }

    // ============ 版本发布 ============

    function publishVersion(
        uint256 _parentVersionId,
        bytes32 _configHash,
        bytes32 _contractHash,
        MigrationMode _migrationMode
    ) external onlyOwner returns (uint256 versionId) {
        // 父版本验证
        if (_parentVersionId != 0) {
            require(versions[_parentVersionId].exists, "CC: parent not found");
        }

        versionId = nextVersionId++;
        versions[versionId] = Version({
            id: versionId,
            parentId: _parentVersionId,
            configHash: _configHash,
            contractHash: _contractHash,
            publishTime: block.timestamp,
            childCount: 0,
            migrationMode: _migrationMode,
            exists: true
        });

        // 更新父版本子计数
        if (_parentVersionId != 0) {
            versions[_parentVersionId].childCount++;
        }

        emit VersionPublished(versionId, _parentVersionId, _configHash, _migrationMode);
        return versionId;
    }

    // ============ 版本 DAG 查询 ============

    function getVersionLineage(uint256 _versionId) external view returns (uint256[] memory) {
        require(versions[_versionId].exists, "CC: version not found");

        // 计算路径长度
        uint256 length = 0;
        uint256 current = _versionId;
        while (current != 0) {
            length++;
            current = versions[current].parentId;
        }

        // 填充路径
        uint256[] memory path = new uint256[](length);
        current = _versionId;
        uint256 index = length;
        while (current != 0) {
            index--;
            path[index] = current;
            current = versions[current].parentId;
        }

        return path;
    }

    function getVersion(uint256 _versionId) external view returns (
        uint256 id,
        uint256 parentId,
        bytes32 configHash,
        bytes32 contractHash,
        uint256 publishTime,
        uint256 childCount,
        MigrationMode migrationMode
    ) {
        Version storage v = versions[_versionId];
        require(v.exists, "CC: version not found");
        return (
            v.id,
            v.parentId,
            v.configHash,
            v.contractHash,
            v.publishTime,
            v.childCount,
            v.migrationMode
        );
    }

    // ============ TOPUP 定价锚定 ============

    function announceTOPUP(
        uint256 _versionId,
        uint256 _oldPrice,
        uint256 _newPrice
    ) external onlyOwner {
        require(versions[_versionId].exists, "CC: version not found");

        // 计算 TWAP（简化：实际应接入预言机）
        uint256 twap = (_oldPrice + _newPrice) / 2;  // 简化 TWAP

        PriceDirection dir;
        if (_newPrice > _oldPrice) {
            dir = PriceDirection.Increase;
        } else if (_newPrice < _oldPrice) {
            dir = PriceDirection.Decrease;
        } else {
            dir = PriceDirection.Same;
        }

        topuPricings[_versionId] = TOPUPricing({
            oldPrice: _oldPrice,
            newPrice: _newPrice,
            announceTime: block.timestamp,
            twapPrice: twap,
            challengeDeadline: block.timestamp + CHALLENGE_WINDOW,
            challenged: false,
            direction: dir
        });

        emit TOPUAnnounced(_versionId, _oldPrice, _newPrice, twap);
    }

    function challengeTOPUP(uint256 _versionId) external {
        TOPUPricing storage t = topuPricings[_versionId];
        require(t.announceTime > 0, "CC: TOPUP not announced");
        require(block.timestamp <= t.challengeDeadline, "CC: challenge window closed");
        require(!t.challenged, "CC: already challenged");

        t.challenged = true;
        emit TOPUChallenged(_versionId, msg.sender);

        // 被质疑后进入 DAO 投票（简化）
        // 实际应调用 GovernanceDAO.propose()
    }

    function getTOPUPStatus(uint256 _versionId) external view returns (
        uint256 oldPrice,
        uint256 newPrice,
        uint256 twap,
        bool canExecute,
        bool challenged,
        PriceDirection direction
    ) {
        TOPUPricing storage t = topuPricings[_versionId];
        bool expired = block.timestamp > t.announceTime + ANNOUNCE_PERIOD;
        return (
            t.oldPrice,
            t.newPrice,
            t.twapPrice,
            expired && !t.challenged,
            t.challenged,
            t.direction
        );
    }

    // ============ 负价差策略 ============

    function executeNegativeSpread(uint256 _versionId) external onlyOwner {
        TOPUPricing storage t = topuPricings[_versionId];
        require(t.direction == PriceDirection.Decrease, "CC: not negative spread");
        require(block.timestamp > t.announceTime + ANNOUNCE_PERIOD, "CC: announce period not ended");
        require(!t.challenged, "CC: challenged");

        // 降价时：旧许可持有者免费迁移，享受更低价格
        // 创作者收入损失由协议补贴（简化）

        // 触发 LicenseNFT 的批量价格调整
        // 简化：实际应调用 licenseContract
    }

    // ============ 链下存储 ============

    function updateChainStorage(
        uint256 _versionId,
        string calldata _ipfsHash,
        bytes32 _merkleRoot
    ) external onlyOwner {
        chainStorages[_versionId] = ChainStorage({
            ipfsHash: _ipfsHash,
            merkleRoot: _merkleRoot,
            pinCount: 3,  // 默认 3 个 pinning 节点
            lastVerified: block.timestamp
        });

        emit ChainStorageUpdated(_versionId, _ipfsHash, _merkleRoot);
    }

    function verifyChainStorage(uint256 _versionId) external view returns (bool) {
        ChainStorage storage s = chainStorages[_versionId];
        if (s.pinCount < 3) return false;
        if (bytes(s.ipfsHash).length == 0) return false;
        if (s.merkleRoot == bytes32(0)) return false;
        return true;
    }

    // ============ 配置管理 ============

    function setConfig(bytes32 _key, uint256 _value) external onlyOwner {
        configKeys[_key] = _value;
        emit ConfigSet(_key, _value);
    }

    function getConfig(bytes32 _key) external view returns (uint256) {
        return configKeys[_key];
    }

    // ============ 批量操作 ============

    function batchPublishVersions(
        uint256[] calldata _parentIds,
        bytes32[] calldata _configHashes,
        bytes32[] calldata _contractHashes,
        MigrationMode[] calldata _modes
    ) external onlyOwner {
        require(
            _parentIds.length == _configHashes.length &&
            _configHashes.length == _contractHashes.length &&
            _contractHashes.length == _modes.length,
            "CC: array length mismatch"
        );

        for (uint i = 0; i < _parentIds.length; i++) {
            this.publishVersion(_parentIds[i], _configHashes[i], _contractHashes[i], _modes[i]);
        }
    }

    receive() external payable {}
}

contracts/EmergencyIntervention.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title EmergencyIntervention
 * @notice 紧急干预系统：标准通道 + 快速通道分级 + 同地址冷却期
 * @dev 基于 v0.4 文档 §3.x
 * 修复：severity链上可验证指标、同地址7天冷却期、快速通道分级
 */
contract EmergencyIntervention {
    using Math for uint256;

    // ============ 枚举 ============

    enum Severity {
        L0_Observation,    // 观察级
        L1_Alert,          // 预警级
        L2_Caution,        // 注意级
        L3_Moderate,       // 中度级（触发标准通道冻结）
        L4_Severe,         // 严重级（单签24h追认）
        L5_Critical        // 危急级（多签立即执行）
    }

    enum InterventionType {
        Freeze,            // 冻结
        Sunset,            // 日落
        Rollback,          // 回滚
        Pause              // 暂停
    }

    // ============ 常量 ============

    uint256 public constant COOLDOWN_STANDARD = 7 days;    // 标准通道冷却期
    uint256 public constant COOLDOWN_FAST_SEV4 = 24 hours; // severity 4 单签24h追认
    uint256 public constant ADDRESS_COOLDOWN = 7 days;     // 同地址7天冷却期
    uint256 public constant MAX_EXTENSIONS = 1;            // 异议延长次数上限

    // ============ 数据结构 ============

    struct Intervention {
        uint256 id;
        address initiator;
        uint256 targetVersionId;
        Severity severity;
        InterventionType interventionType;
        bytes32 evidenceHash;
        uint256 timestamp;
        uint256 executeTime;       // 执行时间（冷却期后）
        bool executed;
        bool cancelled;
        uint256 extensionCount;    // 异议延长次数
        mapping(address => bool) hasVoted;
        uint256 voteCount;
    }

    struct ChainMetrics {
        uint256 fundMovement;      // 资金异动量
        uint256 permissionChange;  // 权限变更幅度
        uint256 timestamp;
    }

    // ============ 状态变量 ============

    mapping(uint256 => Intervention) public interventions;
    mapping(address => uint256) public lastInterventionTime;  // 同地址冷却
    mapping(uint256 => ChainMetrics) public versionMetrics;

    uint256 public nextInterventionId;
    address public owner;
    address public daoContract;
    address public juryContract;

    // ============ 事件 ============

    event InterventionProposed(
        uint256 indexed id,
        address indexed initiator,
        uint256 targetVersionId,
        Severity severity,
        InterventionType interventionType,
        uint256 executeTime
    );
    event InterventionExecuted(uint256 indexed id);
    event InterventionCancelled(uint256 indexed id);
    event InterventionExtended(uint256 indexed id, uint256 newExecuteTime);
    event CooldownEnforced(address indexed addr, uint256 until);

    // ============ 修饰器 ============

    modifier onlyOwner() {
        require(msg.sender == owner, "EI: not owner");
        _;
    }

    modifier onlyDAO() {
        require(msg.sender == daoContract, "EI: not DAO");
        _;
    }

    // ============ 构造函数 ============

    constructor() {
        owner = msg.sender;
    }

    function setDAOContract(address _dao) external onlyOwner {
        daoContract = _dao;
    }

    function setJuryContract(address _jury) external onlyOwner {
        juryContract = _jury;
    }

    // ============ 链上指标验证（severity 不再自报） ============

    function validateSeverity(
        uint256 _versionId,
        uint256 _fundMovement,
        uint256 _permissionChange
    ) public view returns (Severity) {
        // 基于链上可验证指标自动判定 severity
        ChainMetrics storage m = versionMetrics[_versionId];

        uint256 fundRatio = m.fundMovement > 0 ? (_fundMovement * 100) / m.fundMovement : _fundMovement;
        uint256 permRatio = m.permissionChange > 0 ? (_permissionChange * 100) / m.permissionChange : _permissionChange;

        if (fundRatio >= 50 || permRatio >= 50) {
            return Severity.L5_Critical;
        } else if (fundRatio >= 30 || permRatio >= 30) {
            return Severity.L4_Severe;
        } else if (fundRatio >= 15 || permRatio >= 15) {
            return Severity.L3_Moderate;
        } else if (fundRatio >= 5 || permRatio >= 5) {
            return Severity.L2_Caution;
        } else if (fundRatio > 0 || permRatio > 0) {
            return Severity.L1_Alert;
        }
        return Severity.L0_Observation;
    }

    function updateMetrics(
        uint256 _versionId,
        uint256 _fundMovement,
        uint256 _permissionChange
    ) external onlyOwner {
        versionMetrics[_versionId] = ChainMetrics({
            fundMovement: _fundMovement,
            permissionChange: _permissionChange,
            timestamp: block.timestamp
        });
    }

    // ============ 提案干预 ============

    function proposeIntervention(
        uint256 _targetVersionId,
        Severity _severity,
        InterventionType _type,
        bytes32 _evidenceHash
    ) external returns (uint256 id) {
        // 同地址冷却期检查
        require(
            block.timestamp >= lastInterventionTime[msg.sender] + ADDRESS_COOLDOWN,
            "EI: address cooldown active"
        );

        // L5 必须通过链上指标验证
        if (_severity == Severity.L5_Critical) {
            Severity validated = validateSeverity(_targetVersionId, 0, 0);
            require(validated == Severity.L5_Critical, "EI: L5 validation failed");
        }

        id = nextInterventionId++;
        Intervention storage inter = interventions[id];
        inter.id = id;
        inter.initiator = msg.sender;
        inter.targetVersionId = _targetVersionId;
        inter.severity = _severity;
        inter.interventionType = _type;
        inter.evidenceHash = _evidenceHash;
        inter.timestamp = block.timestamp;

        // 分级冷却
        if (_severity == Severity.L5_Critical) {
            // L5：多签立即执行（无冷却，但需3/5陪审团）
            inter.executeTime = block.timestamp;
        } else if (_severity == Severity.L4_Severe) {
            // L4：单签24h追认
            inter.executeTime = block.timestamp + COOLDOWN_FAST_SEV4;
        } else {
            // L3及以下：标准7天冷却
            inter.executeTime = block.timestamp + COOLDOWN_STANDARD;
        }

        lastInterventionTime[msg.sender] = block.timestamp;

        emit InterventionProposed(
            id,
            msg.sender,
            _targetVersionId,
            _severity,
            _type,
            inter.executeTime
        );

        return id;
    }

    // ============ 执行干预 ============

    function executeIntervention(uint256 _id) external {
        Intervention storage inter = interventions[_id];
        require(!inter.executed, "EI: already executed");
        require(!inter.cancelled, "EI: cancelled");
        require(block.timestamp >= inter.executeTime, "EI: cooldown not expired");

        // L5 需要陪审团多签
        if (inter.severity == Severity.L5_Critical) {
            require(msg.sender == juryContract, "EI: L5 requires jury");
        }

        inter.executed = true;
        emit InterventionExecuted(_id);

        // 执行具体干预逻辑（简化）
        // 实际应调用 CreatorConfig 或 LicenseNFT
    }

    // ============ 异议延长（防拖延攻击） ============

    function extendCooldown(uint256 _id) external {
        Intervention storage inter = interventions[_id];
        require(!inter.executed, "EI: already executed");
        require(inter.extensionCount < MAX_EXTENSIONS, "EI: max extensions reached");

        // 仅可在执行前24h内提出异议
        require(
            block.timestamp >= inter.executeTime - 24 hours,
            "EI: too early to extend"
        );

        inter.extensionCount++;
        inter.executeTime += 7 days;  // 延长7天

        emit InterventionExtended(_id, inter.executeTime);
    }

    // ============ 取消干预 ============

    function cancelIntervention(uint256 _id) external onlyDAO {
        Intervention storage inter = interventions[_id];
        require(!inter.executed, "EI: already executed");
        inter.cancelled = true;
        emit InterventionCancelled(_id);
    }

    // ============ 查询 ============

    function getIntervention(uint256 _id) external view returns (
        uint256 id,
        address initiator,
        uint256 targetVersionId,
        Severity severity,
        InterventionType interventionType,
        bytes32 evidenceHash,
        uint256 timestamp,
        uint256 executeTime,
        bool executed,
        bool cancelled,
        uint256 extensionCount
    ) {
        Intervention storage inter = interventions[_id];
        return (
            inter.id,
            inter.initiator,
            inter.targetVersionId,
            inter.severity,
            inter.interventionType,
            inter.evidenceHash,
            inter.timestamp,
            inter.executeTime,
            inter.executed,
            inter.cancelled,
            inter.extensionCount
        );
    }

    function canExecute(uint256 _id) external view returns (bool) {
        Intervention storage inter = interventions[_id];
        return !inter.executed && !inter.cancelled && block.timestamp >= inter.executeTime;
    }

    function getAddressCooldown(address _addr) external view returns (uint256) {
        uint256 lastTime = lastInterventionTime[_addr];
        if (lastTime == 0) return 0;
        uint256 until = lastTime + ADDRESS_COOLDOWN;
        return block.timestamp >= until ? 0 : until - block.timestamp;
    }
}

contracts/ExitGasPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title ExitGasPool
 * @notice 退出权 gas 兜底资金池：创作者强制存 0.1 ETH
 * @dev 基于 v0.4 文档 §3.8，修复：回灌路径
 */
contract ExitGasPool {

    // ============ 常量 ============

    uint256 public constant MIN_CREATOR_DEPOSIT = 0.1 ether;  // 创作者强制存入
    uint256 public constant PROTOCOL_TOPUP_RATE = 200;         // 协议收入 2% 注入池子
    uint256 public constant MAX_GAS_REFUND = 0.05 ether;       // 单次退出 gas 上限

    // ============ 数据结构 ============

    struct CreatorPool {
        uint256 balance;           // 创作者存入的 ETH
        uint256 totalRefunded;     // 累计退还
        bool active;               // 是否激活
    }

    // ============ 状态变量 ============

    mapping(address => CreatorPool) public creatorPools;   // 创作者地址 => 池子
    uint256 public protocolPool;                             // 协议兜底池
    address public owner;
    address public licenseContract;
    address public daoContract;

    uint256 public totalRefunded;     // 累计退还总量
    uint256 public totalDeposited;   // 累计存入总量

    // ============ 事件 ============

    event CreatorDeposit(address indexed creator, uint256 amount);
    event ProtocolTopup(uint256 amount);
    event GasRefunded(address indexed user, address indexed creator, uint256 amount);
    event PoolReplenished(address indexed creator, uint256 amount);

    // ============ 修饰器 ============

    modifier onlyOwner() {
        require(msg.sender == owner, "EGP: not owner");
        _;
    }

    modifier onlyLicense() {
        require(msg.sender == licenseContract, "EGP: not license contract");
        _;
    }

    modifier onlyDAO() {
        require(msg.sender == daoContract, "EGP: not DAO");
        _;
    }

    // ============ 构造函数 ============

    constructor() {
        owner = msg.sender;
    }

    function setLicenseContract(address _license) external onlyOwner {
        licenseContract = _license;
    }

    function setDAOContract(address _dao) external onlyOwner {
        daoContract = _dao;
    }

    // ============ 创作者存入 ============

    function creatorDeposit() external payable {
        require(msg.value >= MIN_CREATOR_DEPOSIT, "EGP: minimum deposit 0.1 ETH");

        CreatorPool storage pool = creatorPools[msg.sender];
        pool.balance += msg.value;
        pool.active = true;
        totalDeposited += msg.value;

        emit CreatorDeposit(msg.sender, msg.value);
    }

    // ============ 协议注入（收入 2%） ============

    function protocolTopup() external payable onlyOwner {
        protocolPool += msg.value;
        emit ProtocolTopup(msg.value);
    }

    // ============ 自动回灌（当创作者池子 < 0.05 ETH） ============

    function replenishPool(address _creator) external onlyDAO {
        CreatorPool storage pool = creatorPools[_creator];
        require(pool.active, "EGP: pool not active");

        if (pool.balance < MIN_CREATOR_DEPOSIT / 2) {
            // 从协议池回灌到创作者池
            uint256 needed = MIN_CREATOR_DEPOSIT - pool.balance;
            uint256 actual = needed > protocolPool ? protocolPool : needed;

            if (actual > 0) {
                protocolPool -= actual;
                pool.balance += actual;
                emit PoolReplenished(_creator, actual);
            }
        }
    }

    // ============ 退还退出 gas ============

    function refundExitGas(
        address _user,
        address _creator,
        uint256 _gasUsed
    ) external onlyLicense returns (uint256 refunded) {
        CreatorPool storage pool = creatorPools[_creator];
        require(pool.active, "EGP: creator pool not active");

        // 计算退还金额（按实际 gas 消耗，上限 0.05 ETH）
        uint256 gasCost = _gasUsed * tx.gasprice;
        refunded = gasCost > MAX_GAS_REFUND ? MAX_GAS_REFUND : gasCost;

        // 优先从创作者池扣
        if (pool.balance >= refunded) {
            pool.balance -= refunded;
        } else {
            // 创作者池不足，从协议池兜底
            uint256 fromPool = refunded - pool.balance;
            require(protocolPool >= fromPool, "EGP: insufficient protocol pool");

            protocolPool -= fromPool;
            pool.balance = 0;
        }

        pool.totalRefunded += refunded;
        totalRefunded += refunded;

        // 转账给用户
        (bool success, ) = payable(_user).call{value: refunded}("");
        require(success, "EGP: refund transfer failed");

        emit GasRefunded(_user, _creator, refunded);

        // 触发自动回灌检查
        if (pool.balance < MIN_CREATOR_DEPOSIT / 2) {
            // 异步触发（实际应通过 keeper 或 DAO）
            // 简化：这里不做自动回灌，留待 DAO 处理
        }

        return refunded;
    }

    // ============ 批量退还（gas 优化） ============

    function batchRefundExitGas(
        address[] calldata _users,
        address[] calldata _creators,
        uint256[] calldata _gasUsed
    ) external onlyLicense {
        require(
            _users.length == _creators.length && _creators.length == _gasUsed.length,
            "EGP: array length mismatch"
        );

        for (uint i = 0; i < _users.length; i++) {
            this.refundExitGas(_users[i], _creators[i], _gasUsed[i]);
        }
    }

    // ============ 查询 ============

    function getPoolInfo(address _creator) external view returns (
        uint256 balance,
        uint256 totalRefunded,
        bool active,
        bool needsReplenish
    ) {
        CreatorPool storage pool = creatorPools[_creator];
        return (
            pool.balance,
            pool.totalRefunded,
            pool.active,
            pool.balance < MIN_CREATOR_DEPOSIT / 2
        );
    }

    function getProtocolPool() external view returns (uint256) {
        return protocolPool;
    }

    function getStats() external view returns (
        uint256 totalDeposited_,
        uint256 totalRefunded_,
        uint256 protocolPool_
    ) {
        return (totalDeposited, totalRefunded, protocolPool);
    }

    // ============ 紧急提现（仅DAO） ============

    function emergencyWithdraw(uint256 _amount) external onlyDAO {
        require(_amount <= address(this).balance, "EGP: insufficient balance");
        payable(daoContract).transfer(_amount);
    }

    receive() external payable {}
}

contracts/GovernanceDAO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title GovernanceDAO
 * @notice 治理DAO：投票权重解耦、activityBoost衰减、MIN_MEMBERS=11
 * @dev 基于 v0.4 文档 §5.x
 * 修复：投票权重与势位引擎解耦、activityBoost衰减、公式完全公开
 */
contract GovernanceDAO {
    using Math for uint256;

    // ============ 常量 ============

    uint256 public daoMinMembers = 3;                   // 初始最小成员数 3，owner可调
    uint256 public constant DAO_MAX_MEMBERS = 21;          // 最大成员数
    uint256 public constant VOTE_DURATION = 7 days;        // 投票期
    uint256 public constant EXECUTE_DELAY = 12 hours;      // 执行延迟（6h→12h）
    uint256 public constant ACTIVITY_DECAY = 1000;         // 每次投票后衰减10%
    uint256 public constant MAX_ACTIVITY_BOOST = 2000;     // 最大activityBoost 20%
    uint256 public constant MIN_ACTIVITY_BOOST = 100;      // 最小activityBoost 1%

    // ============ 数据结构 ============

    struct Member {
        uint256 reputation;        // 信誉分（独立计算，不与势位引擎耦合）
        uint256 baseWeight;        // 基础权重
        uint256 activityBoost;     // 活跃度加成（可衰减）
        uint256 lastVoteTime;      // 上次投票时间
        bool active;               // 是否活跃
    }

    struct Proposal {
        uint256 id;
        address proposer;
        string description;
        bytes callData;
        address target;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 startTime;
        uint256 endTime;
        bool executed;
        bool cancelled;
        mapping(address => bool) hasVoted;
    }

    // ============ 状态变量 ============

    mapping(address => Member) public members;
    address[] public memberList;

    mapping(uint256 => Proposal) public proposals;
    uint256 public nextProposalId;

    address public owner;
    address public emergencyContract;
    address public potentialEngine;

    // ============ 事件 ============

    event MemberAdded(address indexed member, uint256 reputation);
    event MemberRemoved(address indexed member);
    event ProposalCreated(uint256 indexed id, address indexed proposer, string description);
    event VoteCast(uint256 indexed id, address indexed voter, bool support, uint256 weight);
    event ProposalExecuted(uint256 indexed id);
    event ProposalCancelled(uint256 indexed id);
    event ActivityBoostUpdated(address indexed member, uint256 newBoost);

    // ============ 修饰器 ============

    modifier onlyOwner() {
        require(msg.sender == owner, "DAO: not owner");
        _;
    }

    modifier onlyMember() {
        require(members[msg.sender].active, "DAO: not member");
        _;
    }

    modifier onlyEmergency() {
        require(msg.sender == emergencyContract, "DAO: not emergency");
        _;
    }

    // ============ 构造函数 ============

    constructor() {
        owner = msg.sender;
    }

    function setDaoMinMembers(uint256 _newMin) external onlyOwner {
        require(_newMin >= 3 && _newMin <= DAO_MAX_MEMBERS, "DAO: invalid min members");
        daoMinMembers = _newMin;
    }

    function setEmergencyContract(address _emergency) external onlyOwner {
        emergencyContract = _emergency;
    }

    function setPotentialEngine(address _pe) external onlyOwner {
        potentialEngine = _pe;
    }

    // ============ 成员管理 ============

    function addMember(address _member, uint256 _reputation, uint256 _baseWeight) external onlyOwner {
        require(!members[_member].active, "DAO: already member");
        require(memberList.length < DAO_MAX_MEMBERS, "DAO: max members reached");
        require(_reputation <= 10000, "DAO: invalid reputation");

        members[_member] = Member({
            reputation: _reputation,
            baseWeight: _baseWeight,
            activityBoost: MAX_ACTIVITY_BOOST,
            lastVoteTime: 0,
            active: true
        });
        memberList.push(_member);

        emit MemberAdded(_member, _reputation);
    }

    function removeMember(address _member) external onlyOwner {
        require(members[_member].active, "DAO: not member");
        members[_member].active = false;

        for (uint i = 0; i < memberList.length; i++) {
            if (memberList[i] == _member) {
                memberList[i] = memberList[memberList.length - 1];
                memberList.pop();
                break;
            }
        }

        emit MemberRemoved(_member);
    }

    // ============ 投票权重计算（完全公开公式） ============

    function calculateWeight(address _member) public view returns (uint256) {
        Member storage m = members[_member];
        if (!m.active) return 0;

        // 权重 = 基础权重 * (1 + 信誉加成 + 活跃度加成)
        // 信誉加成 = reputation / 10000（最高100%）
        // 活跃度加成 = activityBoost / 10000（可衰减，最高20%）
        // 公式完全公开，与势位引擎解耦

        uint256 reputationBonus = m.reputation;  // 0-10000
        uint256 activityBonus = m.activityBoost; // 0-2000

        uint256 totalBonus = reputationBonus + activityBonus;
        uint256 weight = (m.baseWeight * (10000 + totalBonus)) / 10000;

        return weight;
    }

    // ============ activityBoost衰减 ============

    function _decayActivityBoost(address _member) internal {
        Member storage m = members[_member];
        if (!m.active) return;

        // 每次投票后衰减10%
        uint256 newBoost = (m.activityBoost * (10000 - ACTIVITY_DECAY)) / 10000;
        if (newBoost < MIN_ACTIVITY_BOOST) {
            newBoost = MIN_ACTIVITY_BOOST;
        }
        m.activityBoost = newBoost;

        emit ActivityBoostUpdated(_member, newBoost);
    }

    // ============ 提案 ============

    function propose(
        string calldata _description,
        address _target,
        bytes calldata _callData
    ) external onlyMember returns (uint256 id) {
        require(memberList.length >= daoMinMembers, "DAO: insufficient members");

        id = nextProposalId++;
        Proposal storage p = proposals[id];
        p.id = id;
        p.proposer = msg.sender;
        p.description = _description;
        p.target = _target;
        p.callData = _callData;
        p.startTime = block.timestamp;
        p.endTime = block.timestamp + VOTE_DURATION;

        emit ProposalCreated(id, msg.sender, _description);
        return id;
    }

    // ============ 投票 ============

    function vote(uint256 _proposalId, bool _support) external onlyMember {
        Proposal storage p = proposals[_proposalId];
        require(block.timestamp <= p.endTime, "DAO: voting ended");
        require(!p.hasVoted[msg.sender], "DAO: already voted");
        require(!p.executed, "DAO: already executed");
        require(!p.cancelled, "DAO: cancelled");

        uint256 weight = calculateWeight(msg.sender);
        require(weight > 0, "DAO: zero weight");

        p.hasVoted[msg.sender] = true;

        if (_support) {
            p.forVotes += weight;
        } else {
            p.againstVotes += weight;
        }

        // 衰减 activityBoost
        _decayActivityBoost(msg.sender);
        members[msg.sender].lastVoteTime = block.timestamp;

        emit VoteCast(_proposalId, msg.sender, _support, weight);
    }

    // ============ 执行 ============

    function execute(uint256 _proposalId) external onlyMember {
        Proposal storage p = proposals[_proposalId];
        require(block.timestamp > p.endTime + EXECUTE_DELAY, "DAO: execute delay not met");
        require(!p.executed, "DAO: already executed");
        require(!p.cancelled, "DAO: cancelled");
        require(p.forVotes > p.againstVotes, "DAO: not passed");

        p.executed = true;

        // 执行调用
        (bool success, ) = p.target.call(p.callData);
        require(success, "DAO: execution failed");

        emit ProposalExecuted(_proposalId);
    }

    // ============ 紧急取消（仅紧急干预合约） ============

    function emergencyCancel(uint256 _proposalId) external onlyEmergency {
        Proposal storage p = proposals[_proposalId];
        require(!p.executed, "DAO: already executed");
        p.cancelled = true;
        emit ProposalCancelled(_proposalId);
    }

    // ============ 查询 ============

    function getMemberInfo(address _member) external view returns (
        uint256 reputation,
        uint256 baseWeight,
        uint256 activityBoost,
        uint256 lastVoteTime,
        bool active
    ) {
        Member storage m = members[_member];
        return (m.reputation, m.baseWeight, m.activityBoost, m.lastVoteTime, m.active);
    }

    function getProposal(uint256 _id) external view returns (
        uint256 id,
        address proposer,
        string memory description,
        uint256 forVotes,
        uint256 againstVotes,
        uint256 startTime,
        uint256 endTime,
        bool executed,
        bool cancelled
    ) {
        Proposal storage p = proposals[_id];
        return (
            p.id,
            p.proposer,
            p.description,
            p.forVotes,
            p.againstVotes,
            p.startTime,
            p.endTime,
            p.executed,
            p.cancelled
        );
    }

    function getMemberCount() external view returns (uint256) {
        return memberList.length;
    }

    function hasVoted(uint256 _proposalId, address _member) external view returns (bool) {
        return proposals[_proposalId].hasVoted[_member];
    }
}

contracts/LicenseNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title LicenseNFT
 * @notice ECHO 许可 NFT：使用权 + 扩展权 + 衍生权 + 收益权
 * @dev 基于 v0.4 文档 §2.x
 */
contract LicenseNFT is ERC721, ERC721Enumerable, Ownable {

    // ============ 枚举 ============

    enum LicenseType {
        Usage,      // 使用权
        Extension,  // 扩展权
        Derivative, // 衍生权
        Revenue     // 收益权
    }

    enum LicenseStatus {
        Active,     // 生效中
        Expired,    // 已过期
        Sunset,     // 日落冻结
        Refunded    // 已退款
    }

    // ============ 数据结构 ============

    struct License {
        uint256 id;
        uint256 versionId;       // 关联版本
        LicenseType licenseType; // 许可类型
        LicenseStatus status;    // 状态
        uint256 issueTime;       // 发行时间
        uint256 expiryTime;      // 过期时间
        uint256 price;           // 购买价格
        address creator;         // 创作者
        bytes32 termsHash;       // 条款哈希
    }

    struct SunsetRecord {
        uint256 versionId;
        uint256 freezeTime;      // 冻结时间
        bool newLicensesFrozen;  // 新许可是否冻结
        bool configChangesFrozen;// 配置变更是否冻结
    }

    // ============ 状态变量 ============

    mapping(uint256 => License) public licenses;
    mapping(uint256 => SunsetRecord) public sunsets;
    mapping(uint256 => bool) public versionExists;

    uint256 public nextLicenseId;
    address public creatorConfig;
    address public exitGasPool;

    // ============ 事件 ============

    event LicenseIssued(
        uint256 indexed id,
        uint256 indexed versionId,
        address indexed holder,
        LicenseType licenseType,
        uint256 expiryTime
    );
    event LicenseTransferred(
        uint256 indexed id,
        address indexed from,
        address indexed to
    );
    event LicenseSunset(uint256 indexed versionId, uint256 freezeTime);
    event LicenseRefunded(uint256 indexed id, uint256 refundAmount);
    event VersionRegistered(uint256 indexed versionId);

    // ============ 构造函数 ============

    constructor() ERC721("ECHO License", "ECHOL") Ownable(msg.sender) {}

    function setCreatorConfig(address _config) external onlyOwner {
        creatorConfig = _config;
    }

    function setExitGasPool(address _pool) external onlyOwner {
        exitGasPool = _pool;
    }

    // ============ 版本注册 ============

    function registerVersion(uint256 _versionId) external onlyOwner {
        require(!versionExists[_versionId], "LNFT: version already registered");
        versionExists[_versionId] = true;
        emit VersionRegistered(_versionId);
    }

    // ============ 发行许可 ============

    function issueLicense(
        address _to,
        uint256 _versionId,
        LicenseType _type,
        uint256 _duration,
        uint256 _price,
        address _creator,
        bytes32 _termsHash
    ) external onlyOwner returns (uint256 id) {
        require(versionExists[_versionId], "LNFT: version not registered");

        // 检查 sunset 状态
        SunsetRecord storage sunset = sunsets[_versionId];
        if (sunset.newLicensesFrozen) {
            require(block.timestamp < sunset.freezeTime, "LNFT: new licenses frozen");
        }

        id = nextLicenseId++;
        uint256 expiry = block.timestamp + _duration;

        licenses[id] = License({
            id: id,
            versionId: _versionId,
            licenseType: _type,
            status: LicenseStatus.Active,
            issueTime: block.timestamp,
            expiryTime: expiry,
            price: _price,
            creator: _creator,
            termsHash: _termsHash
        });

        _safeMint(_to, id);

        emit LicenseIssued(id, _versionId, _to, _type, expiry);
        return id;
    }

    // ============ 转让许可 ============

    function transferLicense(address _from, address _to, uint256 _tokenId) external {
        // OpenZeppelin 5.x: _isAuthorized 需 3 个参数 (owner, spender, tokenId)
        require(_isAuthorized(ownerOf(_tokenId), msg.sender, _tokenId), "LNFT: not authorized");
        require(licenses[_tokenId].status == LicenseStatus.Active, "LNFT: not active");
        require(block.timestamp <= licenses[_tokenId].expiryTime, "LNFT: expired");

        _transfer(_from, _to, _tokenId);

        emit LicenseTransferred(_tokenId, _from, _to);
    }

    // ============ Sunset 机制 ============

    function sunsetVersion(
        uint256 _versionId,
        bool _freezeNew,
        bool _freezeConfig
    ) external onlyOwner {
        sunsets[_versionId] = SunsetRecord({
            versionId: _versionId,
            freezeTime: block.timestamp,
            newLicensesFrozen: _freezeNew,
            configChangesFrozen: _freezeConfig
        });

        emit LicenseSunset(_versionId, block.timestamp);
    }

    // ============ 退款（触发退出 gas 退还） ============

    function refundLicense(uint256 _tokenId) external {
        License storage lic = licenses[_tokenId];
        require(lic.status == LicenseStatus.Active, "LNFT: not active");
        require(block.timestamp <= lic.expiryTime, "LNFT: already expired");

        address holder = ownerOf(_tokenId);
        require(msg.sender == holder, "LNFT: not holder");

        lic.status = LicenseStatus.Refunded;

        // 计算退款（按剩余时间比例）
        uint256 elapsed = block.timestamp - lic.issueTime;
        uint256 total = lic.expiryTime - lic.issueTime;
        uint256 refund = (lic.price * (total - elapsed)) / total;

        // 退还 ETH
        (bool success, ) = payable(holder).call{value: refund}("");
        require(success, "LNFT: refund failed");

        // 触发 gas 退还
        if (exitGasPool != address(0)) {
            uint256 gasStart = gasleft();
            // 调用 exitGasPool.refundExitGas() 的 gas 消耗
            // 简化：实际 gas 消耗由 ExitGasPool 计算
        }

        emit LicenseRefunded(_tokenId, refund);
    }

    // ============ 批量发行（gas 优化） ============

    function batchIssueLicenses(
        address[] calldata _tos,
        uint256[] calldata _versionIds,
        LicenseType[] calldata _types,
        uint256[] calldata _durations,
        uint256[] calldata _prices,
        address[] calldata _creators,
        bytes32[] calldata _termsHashes
    ) external onlyOwner {
        require(
            _tos.length == _versionIds.length &&
            _versionIds.length == _types.length &&
            _types.length == _durations.length &&
            _durations.length == _prices.length &&
            _prices.length == _creators.length &&
            _creators.length == _termsHashes.length,
            "LNFT: array length mismatch"
        );

        for (uint i = 0; i < _tos.length; i++) {
            this.issueLicense(
                _tos[i],
                _versionIds[i],
                _types[i],
                _durations[i],
                _prices[i],
                _creators[i],
                _termsHashes[i]
            );
        }
    }

    // ============ 查询 ============

    function getLicense(uint256 _tokenId) external view returns (License memory) {
        return licenses[_tokenId];
    }

    function isLicenseValid(uint256 _tokenId) external view returns (bool) {
        License storage lic = licenses[_tokenId];
        return lic.status == LicenseStatus.Active && block.timestamp <= lic.expiryTime;
    }

    function getLicensesByHolder(address _holder) external view returns (uint256[] memory) {
        uint256 balance = balanceOf(_holder);
        uint256[] memory result = new uint256[](balance);
        for (uint i = 0; i < balance; i++) {
            result[i] = tokenOfOwnerByIndex(_holder, i);
        }
        return result;
    }

    function getSunsetStatus(uint256 _versionId) external view returns (
        bool isFrozen,
        bool newLicensesFrozen,
        bool configChangesFrozen
    ) {
        SunsetRecord storage s = sunsets[_versionId];
        return (
            s.freezeTime > 0,
            s.newLicensesFrozen,
            s.configChangesFrozen
        );
    }

    // ============ 重载 ============

    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    receive() external payable {}
}

contracts/PotentialEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title PotentialEngine
 * @notice 势位评估引擎:NPS + 使用反馈 + Tukey fences 自适应阈值
 * @dev 基于 v0.4 文档 §4.x
 * 修复 X7 review #4 (gas风险) 和 #5 (Tukey水军攻击), Seaman 遗漏 #2 (NPS三道锁)
 */
contract PotentialEngine {
    using Math for uint256;

    // ============ 常量 ============

    uint256 public constant NPS_DENOMINATOR = 10000;  // NPS 精度 0-10000
    uint256 public constant MIN_HOLDING_PERIOD = 7 days;   // NPS 7天持有期(修复遗漏)
    uint256 public constant RATING_COOLDOWN = 30 days;     // NPS 30天频率限制(修复遗漏)
    uint256 public constant WEIGHT_CREATOR = 5000;         // 创作者权重 50%
    uint256 public constant WEIGHT_USER = 5000;            // 使用者权重 50%
    uint256 public constant DISPUTE_THRESHOLD = 1000;      // 争议率 >10% 时使用者权重提升
    uint256 public constant WEIGHT_USER_HIGH_DISPUTE = 6000; // 争议率高时使用者权重 60%
    uint256 public constant EMA_WARMUP_BATCHES = 5;        // EMA冷启动：前5个batch渐进SMA过渡，第6个batch起切EMA
    uint256 public constant EMA_ALPHA_NUMERATOR = 2;        // EMA α = 0.2 (2/10)，新数据权重20%
    uint256 public constant EMA_ALPHA_DENOMINATOR = 10;     // EMA 分母
    uint256 public constant MAX_NPS_HISTORY = 1000;         // NPS 历史最大长度（修复 H4）
    uint256 public constant ANOMALY_STREAK_THRESHOLD = 2;  // 连续2周期异常触发延迟确认
    uint256 public constant MIN_IQR = 3;                   // Tukey IQR 最小值（修复 #5）

    // ============ EMA冷启动状态（round8-fix）============
    mapping(uint256 => uint256) public emaBatchCounter;    // 每个versionId已处理batch数

    // ============ 数据结构 ============

    struct NPSScore {
        uint256 score;           // 0-10000
        uint256 timestamp;       // 评分时间
        uint256 licenseId;       // 关联许可
        bool isValid;            // 是否有效
    }

    struct LicenseInfo {
        uint256 purchaseTime;    // 购买时间
        bool exists;             // 是否存在
    }

    struct PotentialMetrics {
        uint256 npsScore;        // NPS 平均分
        uint256 engagementScore; // 参与度分
        uint256 disputeRate;     // 争议率 (basis points)
        uint256 activityScore;   // 活跃度分
        uint256 potential;       // 综合势位分
    }

    struct Thresholds {
        uint256 upperFence;      // Tukey 上围栏
        uint256 lowerFence;      // Tukey 下围栏
        uint256 iqr;             // 四分位距
        uint256 median;          // 中位数
        uint256 lastUpdated;     // 上次更新时间
    }

    // ============ 状态变量 ============

    mapping(uint256 => NPSScore[]) public npsHistory;     // versionId => NPS 历史
    mapping(uint256 => mapping(address => uint256)) public lastRatingTime; // versionId => user => time
    mapping(uint256 => mapping(uint256 => LicenseInfo)) public licenses; // versionId => licenseId => info
    mapping(uint256 => PotentialMetrics) public metrics;   // versionId => 当前指标
    mapping(uint256 => Thresholds) public thresholds;      // versionId => 阈值
    mapping(uint256 => uint256) public anomalyStreak;      // versionId => 连续异常次数

    address public owner;
    address public juryContract;   // AgentJury 合约地址

    // ============ 事件 ============
    /// @notice 前端可视化规范（round8-fix）
    /// @dev 合约仅抛出事件，前端按以下规范渲染：
    /// - 正常区间（lowerFence ~ upperFence）：绿色折线，无闪烁
    /// - 温和异常（potential 越界 1.5 IQR）：黄色闪烁 + 警告图标
    /// - 极端异常（偏离中位数 >=3 IQR）：红色全屏遮罩 + "延迟确认中"文案
    /// - 连续 ANOMALY_STREAK_THRESHOLD(2) 周期异常：加锁图标 + 倒计时
    ///   （等待人工/Agent陪审团介入，期间禁止自动阈值更新）
    /// - EMA冷启动期（emaBatchCounter < 5）：灰色虚线 + "数据积累中"提示
    ///   第5个batch完成后变实线绿色，前端监听 EMAWarmedUp 事件切换

    event NPSSubmitted(uint256 indexed versionId, address indexed user, uint256 licenseId, uint256 score);
    event NPSInvalidated(uint256 indexed versionId, uint256 indexed licenseId, string reason);
    event EMAWarmedUp(uint256 indexed versionId, uint256 finalSMAValue);
    event ThresholdsUpdated(uint256 indexed versionId, uint256 upper, uint256 lower, uint256 iqr);
    event AnomalyDetected(uint256 indexed versionId, uint256 metric, uint256 fence);
    event DelayedConfirmation(uint256 indexed versionId, uint256 streak);

    // ============ 修饰器 ============

    modifier onlyOwner() {
        require(msg.sender == owner, "PE: not owner");
        _;
    }

    modifier onlyJury() {
        require(msg.sender == juryContract, "PE: not jury");
        _;
    }

    // ============ 构造函数 ============

    constructor() {
        owner = msg.sender;
    }

    function setJuryContract(address _jury) external onlyOwner {
        juryContract = _jury;
    }

    // ============ NPS 提交(三道锁) ============

    function submitNPS(
        uint256 _versionId,
        uint256 _licenseId,
        uint256 _score  // 0-10000
    ) external {
        require(_score <= NPS_DENOMINATOR, "PE: invalid score");

        LicenseInfo storage lic = licenses[_versionId][_licenseId];
        require(lic.exists, "PE: license not found");

        // 锁1:7天持有期(修复遗漏)
        require(
            block.timestamp >= lic.purchaseTime + MIN_HOLDING_PERIOD,
            "PE: holding period not met"
        );

        // 锁2:30天频率限制(修复遗漏)
        uint256 lastTime = lastRatingTime[_versionId][msg.sender];
        require(
            block.timestamp >= lastTime + RATING_COOLDOWN,
            "PE: rating cooldown active"
        );

        // 锁3:许可有效性实时验证
        require(isLicenseValid(_versionId, _licenseId), "PE: license expired or refunded");


        // 记录 NPS
        npsHistory[_versionId].push(NPSScore({
            score: _score,
            timestamp: block.timestamp,
            licenseId: _licenseId,
            isValid: true
        }));

        lastRatingTime[_versionId][msg.sender] = block.timestamp;

        emit NPSSubmitted(_versionId, msg.sender, _licenseId, _score);

        // 触发重新评估（keeper 分批模式）
        _recalculateMetricsBatch(_versionId, 1);  // 先更新 1 个指标，剩余由 keeper 触发

        // 限制历史长度（修复 H4）
        _trimNPSHistory(_versionId);
    }

    function isLicenseValid(uint256 _versionId, uint256 _licenseId) public view returns (bool) {
        // 简化：实际应调用 LicenseNFT 合约验证
        // TODO: 接入 LicenseNFT.isLicenseValid() 外部调用
        LicenseInfo storage lic = licenses[_versionId][_licenseId];
        return lic.exists;
    }

    function _trimNPSHistory(uint256 _versionId) internal {
        NPSScore[] storage history = npsHistory[_versionId];
        if (history.length <= MAX_NPS_HISTORY) return;

        // 超出限制：将最旧的标记为无效（index 0）
        // 注意：Solidity 数组前端删除昂贵，改用标记无效
        uint256 excess = history.length - MAX_NPS_HISTORY;
        for (uint i = 0; i < excess && i < history.length; i++) {
            if (history[i].isValid) {
                history[i].isValid = false;
                emit NPSInvalidated(_versionId, history[i].licenseId, "history overflow");
            }
        }
    }

    // ============ 势位评估(修复 X7 review:keeper 分批模式) ============

    uint256 public constant MAX_METRICS_PER_BATCH = 5;  // 单次最多更新 5 个指标
    mapping(uint256 => uint256) public versionRecalcIndex; // per-versionId 重算索引（修复 H2）

    function recalculateMetrics(uint256 _versionId) external {
        // 任何人都可以触发,但只更新一批
        _recalculateMetricsBatch(_versionId, MAX_METRICS_PER_BATCH);
    }

    function _recalculateMetricsBatch(uint256 _versionId, uint256 _batchSize) internal {
        NPSScore[] storage history = npsHistory[_versionId];
        if (history.length == 0) return;

        // 分批更新：单次只处理 _batchSize 个指标
        uint256 startIdx = versionRecalcIndex[_versionId];  // 修复 H2：per-versionId
        uint256 batchEnd = startIdx + _batchSize;
        if (batchEnd > history.length) batchEnd = history.length;

        // 计算 NPS 平均分（只处理当前批次）
        uint256 totalNPS = 0;
        uint256 validCount = 0;
        for (uint i = startIdx; i < batchEnd; i++) {
            if (history[i].isValid) {
                totalNPS += history[i].score;
                validCount++;
            }
        }

        PotentialMetrics storage m = metrics[_versionId];
        if (validCount > 0) {
            uint256 batchAvg = totalNPS / validCount;

            // round8-fix: EMA冷启动，前5个batch渐进SMA过渡
            uint256 batchCount = emaBatchCounter[_versionId];
            if (batchCount < EMA_WARMUP_BATCHES) {
                // 渐进累积平均：(旧总分 * 计数 + 新值) / (计数 + 1)
                m.npsScore = (m.npsScore * batchCount + batchAvg) / (batchCount + 1);
                emaBatchCounter[_versionId] = batchCount + 1;
                if (batchCount + 1 == EMA_WARMUP_BATCHES) {
                    emit EMAWarmedUp(_versionId, m.npsScore);
                }
            } else {
                // 修复 H1：标准指数移动平均（EMA）
                // EMA_t = α * new_value + (1-α) * EMA_{t-1}
                m.npsScore = (EMA_ALPHA_NUMERATOR * batchAvg + 
                    (EMA_ALPHA_DENOMINATOR - EMA_ALPHA_NUMERATOR) * m.npsScore) 
                    / EMA_ALPHA_DENOMINATOR;
            }
        }

        versionRecalcIndex[_versionId] = batchEnd;
        if (batchEnd >= history.length) {
            versionRecalcIndex[_versionId] = history.length;  // H2 fix: stop at end, no loop
            _checkAnomaly(_versionId);  // full pass complete
        }
    }

    // ============ Tukey Fences 自适应阈值(修复 X7 review:IQR 倍率≥3 直接进异常) ============

    function _checkAnomaly(uint256 _versionId) internal {
        PotentialMetrics storage m = metrics[_versionId];
        Thresholds storage t = thresholds[_versionId];

        // 计算历史指标的中位数和 IQR（只取有效数据）
        uint256[] memory scores = _extractValidScores(_versionId);
        if (scores.length < 4) return; // 数据不足

        (uint256 q1, uint256 median, uint256 q3) = _calculateQuartiles(scores);
        uint256 iqr = q3 - q1;

        // IQR >= 3 兜底（修复 #5）
        if (iqr < MIN_IQR) iqr = MIN_IQR;

        // 标准 Tukey fences：1.5 倍 IQR
        uint256 upperFence = q3 + (iqr * 15) / 10;  // Q3 + 1.5*IQR
        uint256 lowerFence = q1 > (iqr * 15) / 10 ? q1 - (iqr * 15) / 10 : 0;  // Q1 - 1.5*IQR

        // 修复 H3：IQR 倍率检测与 fences 逻辑统一
        // 当前 potential 偏离中位数的 IQR 倍数（H3 fix: *10 避免整数除法盲区）
        uint256 deviation = m.potential > median ? m.potential - median : median - m.potential;
        uint256 iqrMultiplier10 = iqr > 0 ? (deviation * 10) / iqr : 0;

        if (iqrMultiplier10 >= 30) {
            // 极端偏离（>=3.0 IQR），直接进异常，不更新 Tukey 阈值
            // 防止水军用极端值拉偏分位数
            anomalyStreak[_versionId]++;
            emit AnomalyDetected(_versionId, m.potential, upperFence);

            if (anomalyStreak[_versionId] >= ANOMALY_STREAK_THRESHOLD) {
                emit DelayedConfirmation(_versionId, anomalyStreak[_versionId]);
            }
            return;  // 跳过 Tukey 更新
        }

        // 更新阈值
        t.upperFence = upperFence;
        t.lowerFence = lowerFence;
        t.iqr = iqr;
        t.median = median;
        t.lastUpdated = block.timestamp;

        emit ThresholdsUpdated(_versionId, upperFence, lowerFence, iqr);

        // 检测当前指标是否越界（标准 Tukey 1.5 IQR，H3 fix: >=15 即 1.5x）
        if (iqrMultiplier10 >= 15) {
            anomalyStreak[_versionId]++;
            emit AnomalyDetected(_versionId, m.potential, m.potential > upperFence ? upperFence : lowerFence);

            if (anomalyStreak[_versionId] >= ANOMALY_STREAK_THRESHOLD) {
                emit DelayedConfirmation(_versionId, anomalyStreak[_versionId]);
            }
        } else {
            anomalyStreak[_versionId] = 0;
        }
    }

    function _extractValidScores(uint256 _versionId) internal view returns (uint256[] memory) {
        NPSScore[] storage history = npsHistory[_versionId];
        uint256 validCount = 0;
        for (uint i = 0; i < history.length; i++) {
            if (history[i].isValid) validCount++;
        }

        uint256[] memory scores = new uint256[](validCount);
        uint256 idx = 0;
        for (uint i = 0; i < history.length; i++) {
            if (history[i].isValid) {
                scores[idx++] = history[i].score;
            }
        }
        return scores;
    }

    function _calculateQuartiles(uint256[] memory arr) internal pure returns (uint256 q1, uint256 median, uint256 q3) {
        require(arr.length >= 4, "PE: insufficient data");

        // 排序（修复 H4：限制数组大小后冒泡排序可接受，MAX_NPS_HISTORY=1000）
        // 注意：Solidity 中快速排序递归深度受限，小数组冒泡更稳定
        for (uint i = 0; i < arr.length; i++) {
            for (uint j = i + 1; j < arr.length; j++) {
                if (arr[i] > arr[j]) {
                    uint256 temp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = temp;
                }
            }
        }

        uint256 n = arr.length;

        // 中位数
        if (n % 2 == 0) {
            median = (arr[n / 2 - 1] + arr[n / 2]) / 2;
        } else {
            median = arr[n / 2];
        }

        // Q1:前半部分的中位数
        uint256 half = n / 2;
        if (half % 2 == 0) {
            q1 = (arr[half / 2 - 1] + arr[half / 2]) / 2;
        } else {
            q1 = arr[half / 2];
        }

        // Q3:后半部分的中位数
        uint256 start = n % 2 == 0 ? half : half + 1;
        if ((n - start) % 2 == 0) {
            q3 = (arr[start + (n - start) / 2 - 1] + arr[start + (n - start) / 2]) / 2;
        } else {
            q3 = arr[start + (n - start) / 2];
        }

        return (q1, median, q3);
    }

    // ============ 外部查询 ============

    function getMetrics(uint256 _versionId) external view returns (PotentialMetrics memory) {
        return metrics[_versionId];
    }

    function getThresholds(uint256 _versionId) external view returns (Thresholds memory) {
        return thresholds[_versionId];
    }

    function getNPSCount(uint256 _versionId) external view returns (uint256) {
        return npsHistory[_versionId].length;
    }

    // ============ 管理员 ============

    function registerLicense(uint256 _versionId, uint256 _licenseId, uint256 _purchaseTime) external onlyOwner {
        licenses[_versionId][_licenseId] = LicenseInfo({
            purchaseTime: _purchaseTime,
            exists: true
        });
    }

    function invalidateNPS(uint256 _versionId, uint256 _index, string calldata _reason) external onlyJury {
        require(_index < npsHistory[_versionId].length, "PE: invalid index");
        npsHistory[_versionId][_index].isValid = false;
        emit NPSInvalidated(_versionId, npsHistory[_versionId][_index].licenseId, _reason);
    }

    function updateEngagementScore(uint256 _versionId, uint256 _score) external onlyOwner {
        metrics[_versionId].engagementScore = _score;
    }

    function updateDisputeRate(uint256 _versionId, uint256 _rate) external onlyOwner {
        require(_rate <= 10000, "PE: invalid rate");
        metrics[_versionId].disputeRate = _rate;
    }
}

